arguments.content:
:root {
  --bg-color: #0d1117;
  --bg-card: #161b22;
  --bg-hover: #21262d;
  --text-main: #c9d1d9;
  --text-muted: #8b949e;
  --text-heading: #ffffff;
  --accent-color: #00ffcc;
  --accent-hover: #00ccaa;
  --accent-blue: #475F91;
  --border-color: #30363d;
  --code-bg: #010409;
  --sidebar-width: 280px;
  --header-height: 64px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--accent-color);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--accent-hover);
}

h1, h2, h3, h4, h5, h6 {
  color: var(--text-heading);
  margin-bottom: 1rem;
  font-weight: 600;
  line-height: 1.2;
}

h1 { font-size: 3rem; letter-spacing: -0.02em; }
h2 { font-size: 2rem; }
h3 { font-size: 1.5rem; }

p {
  margin-bottom: 1.5rem;
  color: var(--text-muted);
}

code {
  font-family: ui-monospace, SFMono-Regular, Consolas, "Liberation Mono", Menlo, monospace;
  background-color: var(--code-bg);
  padding: 0.2em 0.4em;
  border-radius: 4px;
  font-size: 0.9em;
  color: #e6edf3;
}

pre {
  background-color: var(--code-bg);
  padding: 1rem;
  border-radius: 8px;
  overflow-x: auto;
  border: 1px solid var(--border-color);
  margin-bottom: 1.5rem;
}

pre code {
  background-color: transparent;
  padding: 0;
}

/* Header */
.header {
  height: var(--header-height);
  background-color: var(--bg-card);
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 2rem;
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-logo {
  font-weight: 700;
  font-size: 1.2rem;
  color: var(--text-heading);
  text-decoration: none;
}

.header-nav {
  display: flex;
  gap: 1.5rem;
  align-items: center;
}

.header-nav a {
  color: var(--text-muted);
  font-size: 0.95rem;
  font-weight: 500;
}

.header-nav a:hover, .header-nav a.active {
  color: var(--text-heading);
}

.header-utils {
  display: flex;
  gap: 1rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.6rem 1.2rem;
  border-radius: 6px;
  font-weight: 600;
  font-size: 0.95rem;
  cursor: pointer;
  transition: all 0.2s;
  text-decoration: none;
  border: 1px solid transparent;
}

.btn-primary {
  background-color: var(--accent-color);
  color: var(--bg-color);
}

.btn-primary:hover {
  background-color: var(--accent-hover);
  color: var(--bg-color);
}

.btn-outline {
  background-color: transparent;
  border-color: var(--border-color);
  color: var(--text-heading);
}

.btn-outline:hover {
  background-color: var(--bg-hover);
  border-color: var(--text-muted);
}

/* Layout */
.layout {
  display: flex;
  min-height: calc(100vh - var(--header-height));
}

.sidebar {
  width: var(--sidebar-width);
  background-color: var(--bg-card);
  border-right: 1px solid var(--border-color);
  padding: 2rem 1.5rem;
  flex-shrink: 0;
  transition: transform 0.3s ease, width 0.3s ease, opacity 0.3s ease;
  position: sticky;
  top: var(--header-height);
  height: calc(100vh - var(--header-height));
  overflow-y: auto;
}

.sidebar.collapsed {
  transform: translateX(-100%);
  width: 0;
  padding: 0;
  opacity: 0;
  overflow: hidden;
  border: none;
}

.sidebar-nav ul {
  list-style: none;
}

.sidebar-nav li {
  margin-bottom: 0.5rem;
}

.sidebar-nav a {
  display: block;
  padding: 0.5rem 0.75rem;
  color: var(--text-muted);
  border-radius: 6px;
  font-size: 0.95rem;
}

.sidebar-nav a:hover, .sidebar-nav a.active {
  background-color: var(--bg-hover);
  color: var(--text-heading);
}

.sidebar-toggle {
  background: transparent;
  border: 1px solid var(--border-color);
  color: var(--text-muted);
  padding: 0.5rem;
  border-radius: 6px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1rem;
}

.sidebar-toggle:hover {
  background-color: var(--bg-hover);
  color: var(--text-heading);
}

.main-content {
  flex: 1;
  padding: 4rem;
  max-width: 1000px;
  margin: 0 auto;
  width: 100%;
}

/* Home hero */
.hero {
  text-align: center;
  padding: 4rem 0;
  max-width: 800px;
  margin: 0 auto;
}

.hero h1 {
  font-size: 3.5rem;
  margin-bottom: 1.5rem;
}

.hero p {
  font-size: 1.25rem;
  margin-bottom: 2rem;
}

.hero-ctas {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

/* Cards Grid */
.grid-3 {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.5rem;
  margin-bottom: 4rem;
}

.grid-2 {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 1.5rem;
  margin-bottom: 4rem;
}

.card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 2rem;
  transition: transform 0.2s, border-color 0.2s, box-shadow 0.2s;
  display: flex;
  flex-direction: column;
}

.card:hover {
  transform: translateY(-2px);
  border-color: var(--accent-color);
  box-shadow: 0 4px 20px rgba(0, 255, 204, 0.05);
}

.card h3 {
  margin-bottom: 1rem;
  font-size: 1.25rem;
}

.card p {
  flex: 1;
}

.card-link {
  margin-top: 1.5rem;
  font-weight: 600;
  display: inline-block;
}

/* CLI Setup Section */
.cli-section {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  overflow: hidden;
  margin-bottom: 4rem;
}

.cli-header {
  padding: 2rem;
  border-bottom: 1px solid var(--border-color);
}

.cli-body {
  display: flex;
}

@media (max-width: 768px) {
  .cli-body { flex-direction: column; }
}

.cli-accordions {
  flex: 1;
  border-right: 1px solid var(--border-color);
}

@media (max-width: 768px) {
  .cli-accordions { border-right: none; border-bottom: 1px solid var(--border-color); }
}

.accordion-item {
  border-bottom: 1px solid var(--border-color);
}

.accordion-item:last-child {
  border-bottom: none;
}

.accordion-header {
  padding: 1.5rem 2rem;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: 600;
  color: var(--text-heading);
  background: transparent;
  transition: background 0.2s;
}

.accordion-header:hover {
  background-color: var(--bg-hover);
}

.accordion-header.active {
  border-left: 4px solid var(--accent-color);
  padding-left: calc(2rem - 4px);
  background-color: rgba(0, 255, 204, 0.05);
}

.accordion-content {
  display: none;
  padding: 0 2rem 1.5rem;
  color: var(--text-muted);
}

.accordion-content.active {
  display: block;
}

.accordion-content ol {
  padding-left: 1.5rem;
  margin-top: 1rem;
}

.accordion-content li {
  margin-bottom: 0.5rem;
}

.cli-code {
  flex: 1.5;
  padding: 2rem;
  background-color: var(--code-bg);
}

.tabs {
  display: flex;
  gap: 1rem;
  margin-bottom: 1rem;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 0.5rem;
}

.tab {
  background: transparent;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 0.9rem;
  font-weight: 600;
  padding: 0.5rem 0;
  position: relative;
}

.tab.active {
  color: var(--text-heading);
}

.tab.active::after {
  content: '';
  position: absolute;
  bottom: -0.5rem;
  left: 0;
  right: 0;
  height: 2px;
  background-color: var(--accent-color);
}

.tab-content {
  display: none;
}

.tab-content.active {
  display: block;
}

.code-block {
  margin-top: 1.5rem;
}

.code-block p {
  font-size: 0.85rem;
  margin-bottom: 0.5rem;
}

/* Footer */
footer {
  border-top: 1px solid var(--border-color);
  padding: 4rem 2rem;
  background-color: var(--bg-card);
  margin-top: auto;
}

.footer-grid {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
}

.footer-col h4 {
  color: var(--text-heading);
  margin-bottom: 1rem;
  font-size: 1rem;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 0.5rem;
}

.footer-col a {
  color: var(--text-muted);
  font-size: 0.9rem;
}

.footer-col a:hover {
  color: var(--accent-color);
}

/* Responsive */
@media (max-width: 1024px) {
  .sidebar {
    position: fixed;
    z-index: 50;
    transform: translateX(-100%);
  }
  .sidebar.active {
    transform: translateX(0);
  }
  .main-content {
    padding: 2rem;
  }
}

.mobile-sidebar-toggle {
  display: none;
}

@media (max-width: 1024px) {
  .mobile-sidebar-toggle {
    display: flex;
    background: transparent;
    border: none;
    color: var(--text-heading);
    font-size: 1.5rem;
    cursor: pointer;
  }
  .header-nav {
    display: none;
  }
}
